// Go: extra_test.go:TestDangerousURLStringCase
#[test]
fn dangerous_url_string_case() {
    let md = goldmark::new(vec![]);
    let source = b"[Basic](javascript:alert('Basic'))\n[CaseInsensitive](JaVaScRiPt:alert('CaseInsensitive'))\n";
    assert_eq!(
        convert(&md, source),
        "<p><a href=\"\">Basic</a>\n<a href=\"\">CaseInsensitive</a></p>\n"
    );
}

#[test]
fn text_reader_basics() {
    use text::Reader;
    let src = b"ab\ncd";
    let mut r = text::new_reader(src);
    let (l, _) = r.peek_line();
    assert_eq!(&*l.unwrap(), b"ab\n");
    r.advance(3);
    assert_eq!(r.position().0, 1);
    assert_eq!(r.peek(), b'c');
    r.advance(2);
    assert_eq!(r.peek(), text::EOF);
    assert!(r.peek_line().0.is_none());
}

#[test]
fn markdown_is_send_and_sync() {
    fn assert_send_sync<T: Send + Sync>() {}
    assert_send_sync::<goldmark::Markdown>();
    assert_send_sync::<goldmark::ast::Ast>();
    fn assert_send<T: Send>() {}
    assert_send::<goldmark::parser::Context>();
}

#[test]
fn deep_nesting_on_a_small_stack() {
    // Go recurses on growable goroutine stacks; the port must not overflow
    // a 2 MiB thread stack on deeply nested input.
    let h = std::thread::Builder::new()
        .stack_size(2 << 20)
        .spawn(|| {
            let md = goldmark::new(vec![]);
            let mut src = ">".repeat(20000);
            src.push_str(" a\n");
            src.push_str(&"*".repeat(50000));
            src.push('a');
            src.push_str(&"*".repeat(50000));
            src.push_str("\n![");
            src.push_str(&"*".repeat(20000));
            src.push('a');
            src.push_str(&"*".repeat(20000));
            src.push_str("](x)\n");
            let mut out: Vec<u8> = Vec::new();
            md.convert(src.as_bytes(), &mut out).unwrap();
            out.len()
        })
        .unwrap();
    assert!(h.join().unwrap() > 100_000);
}
